import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易經傳集解卷三十四","description":"周易經傳集解 - 周易經傳集解卷三十四","frontmatter":{"title":"周易經傳集解卷三十四","description":"周易經傳集解 - 周易經傳集解卷三十四"},"headers":[],"relativePath":"classics/jingchuan-jijie/035.md","filePath":"classics/jingchuan-jijie/035.md"}'),r={name:"classics/jingchuan-jijie/035.md"};function c(o,a,l,d,p,j){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易經傳集解卷三十四",tabindex:"-1"},[n("周易經傳集解卷三十四 "),e("a",{class:"header-anchor",href:"#周易經傳集解卷三十四","aria-label":"Permalink to “周易經傳集解卷三十四”"},"​")],-1),e("p",null,"欽定四庫全書周易經傳集解卷三十四 ​宋林栗撰。八卦成列，象在其中矣；因而重之，爻在其中矣；剛柔相推，變在其中矣；繫辭焉而命之，動在其中矣。吉凶悔吝者，生乎動者也。剛柔者，立本者也。變通者，趨時者。吉凶者，貞勝者也。天地之道，貞觀者也；日月之道，貞明者也；天下之動，貞夫一者也。夫乾，確然示人易矣。夫坤隤然示人簡矣。爻也者，效此者也。象也者，像此者也。爻象動乎內，吉凶見乎外，功業見乎變，聖人之情見乎辭。天地之大德曰生，聖人之大寶曰位。何以守位曰仁，何以聚人曰財。理財正辭，禁民為非曰義。上章首論乾坤，次言爻象；此章首言爻象，次論乾坤。聖人反覆贊明，以曉學者。乾坤見於爻象，爻象出於乾坤，求而得之，無他義也。今以八卦成列而觀之，則六十四象在其中矣。因而重之，每卦六畫，則三百八十四爻在其中矣。象成而未推，則先後不可見，故剛柔相推，而六十四象之變在其中矣。爻成而未系，則吉凶不可見，故繫辭而命之以吉凶，則三百八十四爻之動在其中矣。吉凶悔吝生乎動，是以系之辭也。易曰：「動悔有悔，徵吉。」王通乃謂「不動則無悔」，言易者從而和之。生乎天地之間，嗜慾飢渴，猶夫人也，而欲不動，得乎哉？至言「功業見乎變」，則又不得而惡夫動矣。是故剛柔相推，以立一卦之本；六爻變通，以趨一卦之時；吉凶悔吝，以辨六爻之勝。此聖人之所以為易者也，豈曰「不動」云乎哉？其曰「吉凶者，貞勝」，何謂也？剛勝則柔伏，柔勝則剛陵。卦必有本，有本斯有時；爻必有正，有正斯有勝。爻之正者，卦之本也；爻之勝者，卦之時也。其吉凶之辭，則視其所以為正者，勝與不勝而已。勝則系之以吉，不勝則系之以兇。何謂正？所以為天地之正者，萬物可見是也，故曰「貞觀」。所以為日月之正者，天下常明是也，故曰「貞明」。所以為天下之正者，民無二王是也，故曰「貞一」。萬物不可見，則天地息矣；天下不常明，則日月廢矣；民不知有君，則天下亂矣。故卦必立之本，爻必取其正，然後視其剛柔之勝，以為吉凶悔吝之辭也。是故有貞吉，有貞兇，有利貞，有勿用貞，有可貞，有不可貞，有貞厲，有貞悔亡，有貞吝，有貞無咎。而說者乃曰：「吉凶之來，唯正可以勝之。」若是則一言而足矣，又何尚於易乎？夫微子去之，箕子為之奴，比干諫而死，彼三人者，孰為正勝也哉？或曰：乾坤成列，而易列乎其中矣；八卦成列，而象在其中矣。何以異乎？曰：無以異也。八卦之為六十四，重之而可見也。乾坤之為六十四，變之而可見也。方其未重未變也，果安在乎？固以先立乎其中矣。確，剛貌也。易言：「確乎其不可拔也。」隤，柔貌也。禮言：隤乎其順也。乾剛之粹，故其體確然，而示人以易知。坤柔之純，故其體隤然，而示人以簡能。惟簡且易，故變於六十四卦，動於三百八十四爻，而所以為確然之剛，隤然之柔者，常自若也。是故爻也者，效其剛柔者也；象也者，像其剛柔者也。象有變通，辭有鼓舞，故爻象動乎內，而吉凶見乎外。禍可轉而為福，敗可因而為成，故功業見乎變。事有若難而易，𫝑有若危而安，故聖人之情見乎辭。天地之德大矣，語其大者，莫大於生也。生也者，變化是也，其在易則生生是也。聖人之寶大矣，語其大者，莫大於位也。位也者，尊卑是也，其在易則六位是也。天地之道，剛與柔也。聖人之道，仁與義也。以財聚人，以人守位，則謂之仁；以正理財，以理禁民，則謂之義。仁義之不可偏用，猶陰陽之不可偏勝也。聖人之用仁義也，猶天地之用陰陽也，豈可以跡而求之哉？非正不可以理財，非財不可以聚人，非理不可以禁民，非民不可以守位。故天地之化成也，不知其孰為陰，孰為陽；聖人之化成也，不知其孰為仁，孰為義。此易之道，所以與天地聖人為一者也。蘇氏曰：「理財者，疏理其出入之道，使不壅也。」正辭，正名也。無道之世，唯不正其名，故上有愧於辭，而下不直其上。令之不得，誅之不止，何以禁民之為非也。斯言得之矣。古者包犧氏之王天下也，仰則觀象於天，俯則觀法於地，觀鳥獸之文，與地之宜，近取諸身，遠取諸物，於是始作八卦，以通神明之德，以類萬物之情。作結繩而為網罟，以佃以漁，蓋取諸離。包犧氏沒，神農氏作。斲木為耜，揉木為耒，耒耨之利，以教天下，蓋取諸益。日中為市，致天下之民，聚天下之貨，交易而退，各得其所，蓋取諸噬嗑。神農氏沒，黃帝、堯、舜氏作，通其變，使民不倦，神而化之，使民宜之。易窮則變，變則通，通則久。是以「自天祐之，吉無不利」。黃帝、堯、舜垂衣裳而天下治，蓋取諸乾坤。刳木為舟，剡木為楫，舟楫之利，以濟不通，致遠以利天下，蓋取諸渙。服牛乘馬，引重致遠，以利天下，蓋取諸隨。重門擊柝，以待暴客，蓋取諸豫。斷木為杵，掘地為臼，臼杵之利，萬民以濟，蓋取諸小過。弦木為弧，剡木為矢，弧矢之利，以威天下，蓋取諸暌。上古穴居而野處，後世聖人易之以宮室，上棟下宇，以待風雨，蓋取諸大壯。古之葬者，厚衣之以薪，葬之中野，不封不樹，喪期無數，後世聖人易之以棺槨，蓋取諸大過。上古結繩而治，後世聖人易之以書契，百官以治，萬民以察，蓋取諸夬。是故易者，象也。象也者，像也；彖者，材也；爻也者，效天下之動者也。是故吉凶生而悔吝著也。前章既言象之所以像，爻之所以效，此章遂言聖人觀象以備物致用，立成器以為天下利也。包犧，一曰伏羲，或言其姓氏之義，或言其年世之數，自漢以來難知矣。要之，古聖人始作八卦者也。「觀象於天」，觀其確然者也。「觀法於地」，觀其隤然者也。「觀鳥獸之文」，龍虎鳥龜是也。「觀地之宜」，山川原隰是也。在天有其象者，在地有其法；在地有其宜者，在天有其文。「近取諸身」，志氣形骸是也；「遠取諸物」，禽獸草木是也。在我有其理者，在物有其生。在物有其知者，在我有其義。聖人以天地人物而參諸身，於是始作八卦。是故天地有神明之異，通其德則匪殊；物我有靈昧之殊，類其情則為一。神明之德，萬物之情，既已包括乎爻象之中，則備物致用，唯聽所取而已。此聖人得天下之至賾，取諸物宜而不可惡者也。試遞言之。「上目為罔，下目為罟」，畋漁之象也。離為目，為飛鳥，為魚鱉。巽為繩，兌為澤。結其繩，張其目，高則飛鳥麗之，下則魚鱉麗之。蓋取諸離象，然後畋漁之象備之。「上木為耒，下木為耨」，耒耨之象也。震為動，坤為土，艮為堅木，巽為入，而又有「兌」象焉。兌為金。木用其堅，金致其銳，動而入土，土乃發生，然後耒耨之象備矣。「日麗乎上，足動乎下」，日中為市之象也。震為動，艮為止，坎為通，離為麗，動為止，易通與麗交，然後交易之象備矣。上尊為衣，下卑為裳，衣裳之象也。「乾為大赤」，非「坤」則不為玄。「坤為大黑」，非「乾」則不為纁。乾坤成列，而後衣裳之象備矣。木行於上，水流於下，舟楫之象也。「坎」為水，震為足，艮為手，巽為木，兌為金。金以制木，木以行水，人之手足動乎其中，然後舟楫之象備矣。足共其事，口仰於人，牛馬之象也。震為動，艮為止，巽為木，兌為金。金以為銜，木以為梏，隨人而作，隨人而止，然後服牛乘馬之象備矣。內闔其門，外鳴其柝，備豫之象也。坤為夜，為闔戶。艮為徑路、為門闕。坎為盜，為隱伏。震為嗚，為大塗。夫盜晝伏夜動，或潛於徑路，或出於大塗，或伏於門闕。主人闔其戶，鳴柝而驚之，然後重門擊柝之象備矣。土止於下，木動於上，臼杵之象也。艮為土，又為手，巽為木，兌為金，震為足。斷木為杵，掘地為臼。木、金以為器，手、足以為用，然後杵臼之象備矣。毀折為弧，戈兵為矢，弧矢之象也。兌為金，離為火、為電、為矢，坎為弓，巽為木。以金治材，以為弧矢，以威天下，如火如電，然後弧矢之象備矣。下天為宇，上木為棟，宮室之象也。乾為天，兌為澤，震為木，巽為風，艮為闕。風行於木，澤上於天，而巍然門闕，不動乎上，然後宮室之象備矣。木周其內，金錮其外，棺槨之象也。巽為木，為入，乾為人，兌為金，為剛滷之地。木以為藏，金以為固，內外周身，以入於土，然後棺槨之象備矣。君用其剛，民從其決，書契之象也。乾為金，兌為口，巽為繩，又為本。以金削木而為契，以口諧聲而為書記，文明遂以代結繩之政，然後書契之象備矣。是故觀乎重離，則見上網下罟之象；「觀乎益」，則見上耒下耜之象；「觀乎噬嗑」，則見三陽為人，三陰為貨，交易之象；「觀乎乾坤」，則見六幅為衣，十二幅為裳，尊卑之象；「觀乎渙」，則見人動乎上，楫動乎下，舟行之象；「觀乎隨」，則見服牛乘馬，引重之象；「觀乎豫」，則見內外重門，閉固之象；觀乎小過，則見臼杵、椎舂之象；觀乎暌，則見張弧挾矢之象；觀乎大壯，則見宮室、門闕之象；觀乎大過，則見輿棺輦槨之象；「觀乎夬」，則見書契、緘縢之象。聖人豈苟云乎哉？然而獨於黃帝、堯、舜言「通其變，使民不倦，神而化之，使民宜之」，何也？豈包犧、神農之時未能變通也？或曰：「不然。所謂變化者，乾坤之道也，取諸乾坤，故不得不兼言乎變化也。」又曰：「易窮則變，變則通，通則久，不於它卦而獨於此，何謂也？」曰：「乾坤，易之縕也，取諸乾坤，故不得不兼言乎易也。」其在他卦，豈得而該徧之哉？故曰：易者，象也；象也者，像其形容也。彖者，材也；材也者，辨其材用也。爻也者，效也，效天下之動也。既效其動，是故吉凶生而悔吝著也。蘇氏曰：「彖，彖也。爻折俎，包犧象之矣。」或曰：伏羲始畫八卦，文王重易六爻。方其未重也，備物致用，於何而取之？曰：八卦成列，象在其中矣；因而重之，爻在其中矣。至於文王，實始作易，布其爻而系之辭，前乎此者，未嘗無六十四也。周官三易，蓋有之矣。然包犧作結繩為網罟，神農作耒耜通交易，黃帝、堯、舜垂衣裳而作舟楫，服牛乘馬，重門擊柝，臼杵弧矢，棟宇書契，皆在三易之前，蓋得其意云爾，非必即其書而取其義，因其象而致其用也。子云：「上古結繩而治，後世聖人易之以書契，百官以治，萬民以察，蓋取諸夬。」然則未有書契以前，安得夬卦而取之哉？近世學者，必欲言伏羲既畫八卦，又因而重之者，非矣。陽卦多陰，陰卦多陽，其故何也？陽卦奇，陰卦耦。其德行何也？陽一君而二民，君子之道也。陽二君而一民，小人之道也。易曰：「憧憧往來，朋從爾思。」子曰：「天下何思何慮？」天下同歸而殊塗，一致而百慮，天下何思何慮？「日往則月來，月往則日來，日月相推而明生焉。寒往則暑來，暑往則寒來，寒暑相推而歲成焉。往者屈也，來者信也，屈信相感而利生焉。尺蠖之屈，以求信也。龍蛇之蟄，以存身也。精義入神，以致用也。利用安身，以崇德也。過此以往，未之或知也。窮神知化，德之盛也。」易曰：「困於石，據於蒺藜，入於其宮，不見其妻，兇。」子曰：「非所困而困焉，名必辱；非所據而據焉，身必危。既辱且危，死期將至，妻其可得見邪？」易曰：「公用射隼於高墉之上，獲之，無不利。」子曰：「隼者，禽也；弓矢者，器也；射之者，人也。君子藏器於身，待時而動，何不利之有？動而不括，是以出而有獲，語成器而動者也。」子曰：「小人不恥不仁，不畏不義，不見利不勸，不威不懲。小懲而大誡，此小人之福也。易曰：屨校滅趾，無咎。此之謂也。」「善不積，不足以成名；惡不積，不足以滅身。小人以小善為無益而弗為也，以小惡為無傷而弗去也，故惡積而不可揜，罪大而不可解。易曰：何校滅耳，兇。」子曰：「危者，安其位者也；亡者，保其存者也；亂者，有其治者也。」是故君子安而不忘危，存而不忘亡，治而不忘亂，是以身安而國家可保也。易曰：其亡其亡，繫於苞桑。子曰：「德薄而位尊，知小而謀大，力小而任重，鮮不及矣。易曰：鼎折足，覆公餗，其形渥，兇。言不勝其任也。」子曰：「知幾其神乎？君子上交不諂，下交不瀆，其知幾乎？幾者，動之微，吉之先見者也。君子見幾而作，不俟終日。易曰：介於石，不終日，貞吉。介如石焉，寧用終日，斷可識矣。君子知微知彰，知柔知剛，萬夫之望。」子曰：「顏氏之子，其殆庶幾乎？有不善，未嘗不知之者，未嘗復行也。易曰：不遠復，無祗悔，元吉。天地絪縕，萬物化醇。男女搆精，萬物化生。易曰：三人行，則損一人；一人行，則得其友。言致一也。」子曰：「君子安其身而後動，易其心而後語，定其交而後求。君子修此三者，故全也。危以動，則民不與也；懼以語，則民不應也；無交而求，則民不與也。莫之與，則傷之者至矣。易曰：莫益之，或擊之，立心勿恆，兇。」前章既言十三卦之象，此章遂言十卦之爻，所謂天下之至動，觀其會通而不可亂者也。陽以一為君而二為民，陰以二為君，而一為民。此陽卦之所以多陰，陰卦之所以多陽，民多而君少，其故然也。一君二民，君子之道；二君一民，小人之道。此陽卦之所以奇，陰卦之所以耦。奇尊而耦卑，奇貴而耦賤，其德行然也。陽出於「乾」，君之象也。陰出乎「坤」，民之象也。「震」「坎」「艮」一陽而二陰，是「乾」為君而「坤」為民也。「巽」「離」「兌」一陰而二陽，是「坤」為君而「乾」為民也。此其所以為君子小人之道歟！易曰：「憧憧往來，朋從爾思。」「鹹」九四之辭也。「鹹」，感也。柔上而剛下，二氣感應以相與，所以為「鹹」也。其在六爻，三陰三陽，各有其配。五應在二，比於上而志乎末；三應在上，比於二而執乎下。故三與五兩朱其民，而二與四皆畔其君，何也？三五皆以剛居剛，而體乎「乾」，二四皆以柔居柔，而體乎「巽」。漠然無相與之意，欲其感應，難矣。惟初六以陰居剛，九四以陽居柔，而又「艮」下「兌」上，得乎相與之義。其應既專，其情且速，故其往來相求，中心憧憧然，如恐弗獲也。感應之道，固如是矣。故曰「貞吉悔亡」。或曰：九五、六二，陰陽並毗，剛上柔下，固無相與之義也。九三、上六雖曰並毗，而柔上剛下，二氣感應，謂之相與，不亦可乎？初六、九四雖陰陽互居，而剛上柔下，於鹹之道亦有未至，然其得失臧否若是不同，何也？曰：三乾震也，而上為巽，是二君而一民也。四上下兌也，而初為民，是二民而一君也。震巽為長，艮兌為少，此其所以辨之與？思者，心也。朋者，眾也。四於六爻，心之謂也。下兌上兌，朋之象也。愛人者，人恆愛之。敬人者，人恆敬之。君之視臣如手足，則臣視君如腹心。朋從爾思，不亦宜乎？然以位則未光，以時則未大，故猶有憧憧之辭也。夫子言之曰：「天下何思何慮？天下同歸而殊塗，一致而百慮，天下何思何慮？」以心觀心，千萬人之心，一人之心是也。夫又別有何思，別有何慮哉？又曰：「往者屈也，來者信也，屈信相感而利生焉。」往者為屈，男下女也；來者為信，婦從夫也。我往則彼來，我不肯往，彼曷為來哉？有屈則有信，身不肯屈，道何自信哉？詩云：「莫往莫來，悠悠我思。」則異乎憧憧朋來之義矣。故以日月寒暑明往來之義，又以尺蠖龍蛇辨屈信之理。不往則不來，不屈則不信也。夫往來之義，日月寒暑所不免，而況於人乎？屈信之理，尺蠖龍蛇且猶知之，而況於人乎？天地之運，人物之情，莫不皆然，可謂殊塗而同歸，百慮而一致矣。故又曰：「精義入神以致用也；利用安身以崇德也。」精乎屈信往來之義而入於神，非特退藏於密也，亦將以致其用也。利乎屈信往來之用而安其身，非特與民同患也，亦將以崇其德也。或曰：精義入神，何謂也？曰：窮理而至於命也。利用安身，何謂也？曰：利物者，所以自安也。龍蛇之蟄，但言存身者，身存則卒起而變化矣。故雖聖人，猶以安身為本，身安而後德可崇也。出而致用，入而崇德，亦往來屈信之理。過此以往，則外化內神之事也。孟子曰：「大而化之之謂聖，聖而不可知之之謂神。」又曰：「所過者化，所存者神。」傳曰：「一則神，兩則化。」由是言之，亦往來屈信之理也。夫子以其難言，而當世之人不足與有明也，故曰「未之或知也」。窮神知化，德之盛也。惟盛德者，為能窮而知之矣。或曰：鹹之九四，足以充窮神知化之事乎？曰：不然。詩之駉曰「思無邪」，本言牧馬之事，非言詩也。而夫子取其一言，言詩之大旨，曰：詩三百，一言以蔽之，曰思無邪。今鹹之九四曰：憧憧往來，朋從爾思，本言上下感應之事，非言易也。而夫子取其一言，言易之大旨，自日月寒暑之章章，至於窮神知化之微妙，皆一以貫之，所謂「觀其所感，而天地萬物之情可見」者也。古人斷章取義，多如是矣。故自此以下，錯舉諸卦之爻，以明著其例，或在初上，或在二三四，而各主一卦之義，獨不舉五爻者，志可知矣。凡此十爻，其初為君子，其五為小人，獨噬嗑舉其二者，初上為小人，終始故也。苟不求其故，考其德行，何從而見之哉？逐爻之義，各釋於本卦。子曰：乾坤，其易之門邪？乾，陽物也。坤，陰物也。陰陽合德，而剛柔有體，以體天地之撰，以通神明之德。其稱名也，雜而不越，於稽其類，其衰世之意邪？夫易彰往而察來，而微顯闡幽，開而當名辨物，正言斷辭，則備矣。其稱名也小，其取類也大。其旨遠，其辭文，其言曲而中，其事肆而隱。因二以濟民行，以明失得之報。此一節為簡編脫亂，失其倫次。自「通神明之德」，下文當曰：「其稱名也小，其取類也大。」至「明失得之報」，下文當曰：「其稱名也，雜而不越。於稽其類，其衰世之意邪？」脫一簡在後，後脫二簡在前。妄儒小生，記誦不精，從而次之，故繆紊若此也。「微顯闡幽」下有「開」字，蓋書生注於句絕，以訓釋「闡」字耳，非本文也。夫子既言十三卦之象、十卦之爻，此章復言其皆自乾坤而出也，故曰「乾坤其易之門」也。或曰：「易之縕，易之門」，有以異乎？曰：無以異也。言其具乎中，則謂之縕，言其所由出則謂之門。縕，蓋藏也。門，闔闢也。乾為健為天，陽之物也。坤為順為地，陰之物也。陰陽合德而後能生剛柔，有體而不可易。變化者，天地之撰也。易簡者，神明之德也。天地之撰，一生一成，以此而體。神明之德，一動一靜，以此而通。其稱名也，曰「乾」曰「坤」，可謂小矣。其取類也，為天為地，可謂大矣。及其成書也，既往無不彰，方來無不察，至顯無不微，至幽無不闡，名無不當，物無不辨，言無不正，辭無不斷，則可謂備矣。彰往察來，故遠而文；微顯闡幽，故肆而隱。當名辨物，故雜而不越；正言斷辭，故曲而中。夫易本於畫，畫不足，故稱其名。名者，彖也，乾、坤、屯、蒙、需、訟、師、比是也。名不足，故辨諸物。物者，象也，「潛龍」、「見龍」、「履霜、堅冰」是也。物不足，故正言之。正言之者，「終日乾乾，夕惕若」之類是也。言不足，故斷以辭。斷以辭者，「勿用利見」，「厲無咎」之類是也。或曰：「何謂肆而隱？」曰：發揮天下之至賾，故幽者闡而肆；包羅天下之至動，故顯者隱而微。剛柔動靜，是之謂貳；吉凶悔吝，是之謂因。因其貳以為吉凶，所以明失得之報，以濟斯民之行也。「何謂雜而不越？」曰：大畜、小畜，皆畜也；大過、小過，皆過也。屯，難也；蹇，亦難也。晉，進也；漸，亦進也。臨，大也；禮，亦大也。然而臨不可以為豐，漸不可以為晉，大畜不可以為小畜，小過不可以為大過，此所謂雜而不越也。於是焉而稽其類，則見聖人測隱憂患之心，故曰：其衰世之意耶？非衰世人，則其操心不能若是之危，而慮患不能若是之深矣。易之興也，其於中古乎？作易者，其有憂患乎？是故履，德之基也；謙，德之柄也；復，德之本也；恆，德之固也；損，德之修也；益，德之裕也；困，德之辨也；井，德之地也；巽，德之制也。履，和而至；謙，尊而光；復，小而辨於物；恆，雜而不厭；損，先難而後易；益，長裕而不設；困，窮而通；井，居其所而遷；巽，稱而隱。履以和行，謙以制禮，復以自知，恆以一德，損以遠害，益以興利，困以寡怨，井以辨義，巽以行權。夫子既言易有衰世之意，此章遂言九卦之大義，以見聖人憂患之心，故曰：「易之興也，其於中古乎？」夫易作於文王，成於周公，夫子蓋知之矣。然猶若疑而嘆之，何也？曰：夫子當週之衰，行乎憂患之域，所遭所歷，變故萬端，而作易者皆已預言之，如足履而目見之者，非文王、周公，其誰系之？此夫子所以若發疑而深嘆之也。九卦之義，各隨其彖釋之。易之為書也不可遠，為道也屢遷，變動不居，周流六虛，上下無常，剛柔相易，不可為典要，唯變所適。其出入以度，外內使知懼。又明於憂患與故，無有師保，如臨父母。初率其辭而揆其方，既有典常，苟非其人，道不虛行。夫子既言十三卦之象、十卦之爻、九卦之彖，蓋舉一隅之意耳。此三章遂明易之為書，不可遠，不可執，始終條理，廣大悉備，學者深求而後得之也。中庸曰：「道也者，不可須臾離也，可離非道也。」又曰：「道不遠人，人之為道而遠人，不可以為道。」故易之為書，切於斯人起居出入、視聽言動之間，君子造次顛沛必於是也。書曰：「德無常師，主善為師。善無常主，協於克一。」故易之為書，雖不可遠，然其為道也屢遷，亦不可執一以求之也。何為其然也？以其升降往來，變動不居，而周流乎六虛之位，是以屢遷而不可遠也。貴不必上，賤不必下，是謂無常。剛往則柔來，柔往則剛來，是謂相易。不可定之以為典常，不可總之以為要會，唯其變化所適，則從而求之可也。外卦為出，內卦為入。凡易之內外出入者，所以為民外內出入之度，使之觀其吉凶而知所戒懼也。又明示以憂患之故，使知其微漸而早圖之，聖人之意可謂勤矣。「與」字當為「之」字之誤。說者謂明憂患與其故，雖若無害於理，然上文使知懼，則既明憂患矣，此又中言之，何哉？師，父道也；保，母道也。師保之前，如臨父母，宜也。今旡師保在前，而嚴憚其辭，愛戴其德，如父母實臨之，何也？蓋以聖人之作易，其於天下後世，不啻如其父母師保之心也。率，循也。揆，度也。方，所也。既，終也。學者之讀其書，能如父母師保之臨其前，然後循其同異之辭，以度其屢遷之所由始而極其終，則雖千變萬化，終冇典常，其條理粲然，不可紊也。故曰：「苟非其人，道不虛行。」記曰：「甘受和，白受採，小人不知天命而不畏也。」則其侮聖人之言宜矣。而望道之行，知是書之不可遠，不亦難乎？或曰：此章既言「不可為典要」，又曰「既有典常」，何也？曰：德無常師，主善為師，則善者其常也。善無常主，協於克一，則一者其常也。是故上下旡常，剛柔相易，則不可為典要矣。同歸而殊塗，百慮而一致，是豈不可為典常哉？今之言易者，或睹其形似而妄一其義，及其不可通，則又妄二其說。從而詰之，則曰「易不可為典要」者也。豈不繆哉？易之為書也，原始要終，以為質也。六爻相雜，唯其時物也。其初難知，其上易知，本末也。初辭擬之，卒成之終。若夫雜物撰德，辨是與非，則非其中爻不備。噫！亦要存亡吉凶，則居可知矣。知者觀其彖辭，則思過半矣。二與四同功而異位，其善不同，二多譽，四多懼，近也。柔之為道，不利遠者，其要無咎，其用柔中也。三與五同功而異位，三多兇，五多功，貴賤之等也。其柔危，其剛勝邪？前章既言易有典常，此章遂論其統要之所在。說文曰：「質，主也。」原其始於初，要其終於上，以為一卦之主也。雖六爻相雜，疑若難明，唯其物之當乎時，斯為主矣。其初難知，其上易知者，本藏而末見，積累之微，而成效之著，依違之未定，而向背之已明也。故爻之辭，初而擬之，卒而成之。「擬之」者，言其未定也。「成之」者，言其已然也。「終」字亦衍文。卒之為言終也，與前章衍「開」字同。若夫雜以陰陽之物、剛柔之撰、仁義之德，而辨其是非，則非其中爻不備。何者？本末雖在於初上，而是非決於中爻也。中爻者，二三四五是也。二三四五俱謂中爻，何也？曰：由三畫而言之，則二五為中；由六畫而言之，而三四為中；由初上而言之，則二三四五俱為中也。求本末於初上，辨是非於中爻，夫豈易哉？故夫子從而噫之，以為學者苟求之而弗得，亦不過要其如是而存，如是而亡，如是而吉，如是而兇，則居然可知矣。存亡吉凶，爻則有之，而彖辭固已指其所在，是以智者觀之，思過半矣。二與四，三與五，剛柔同而上下異之，以其善不同。「二多譽，四多懼」，何也？二遠而四近也。柔而近尊，進退危疑，是以多懼也。遠既無咎，柔又得中，是以多譽也。「三多兇，五多功」，何也？五貴而三賤也。三五皆柔，則三危而五不危，是以多兇也。三、五皆剛，則五勝而三不勝，是以多功也。學者以此辨其中爻，而原始要終，以為其質，考其時物，觀其彖辭，將無餘蘊矣，烏在其不可為典要也哉？一雲：柔之為道，有利不利，文脫二字。亦或然矣。易之為書也，廣大悉備，有天道焉，有人道焉，有地道焉。兼三才而兩之，故六。六者非它也，三才之道也。道有變動，故曰爻。爻有等，故曰物。物相雜，故曰文。文不當，故吉凶生焉。前章既言六爻之辨，此章遂論其本諸三才而悉備，故曰：「夫易廣矣，大矣，備矣。」說卦曰：「立天之道，曰陰與陽；立地之道，曰柔與剛；立人之道，曰仁與義。」是謂兼三才而兩之，故曰：六爻之動，三極之道也。道有變動，故曰爻。爻者，效也。爻有等衰，故曰物。物者，象也。物相雜，故曰文。文者，經緯也。位以為經，爻以為緯，錯而成文。文有當不當，故吉凶生焉。當不當雲者，爻位相得不相得故也。故曰吉凶者，言乎其失得也。凡此之義，二篇之中反覆言之，不一二見而已。考其辭旨重複，不類他經之簡嚴，故近世儒者或疑二篇之文非夫子之作，不知夫子所以贊易為傳而不為經，其體固如此也。為是說者，讀易而不知其義者也。苟知其義，則無是言矣。子貢曰：「君子一言以為智，一言以為不智，言不可不慎也。」信哉！易之興也，其當殷之末世，周之盛德邪？當文王與紂之事邪？是故其辭危。危者使平，易者使傾，其道甚大，百物不廢，懼以終始，其要無咎，此之謂易之道也。前三章言易之為書備矣，此章遂申明是書作於文王，而成於周公。夫周公既已作禮樂以維持當世，措之於太和之域，而是書蓋衰世憂患之意，辭旨淵奧，非中材小智所可窺測，故存其書而不著其人，將有待於後聖，而世或未之知也歟？夫子是以三嘆而言之也。然則夫子何以知之？以其辭危而知之也。夫殷之未亡，賢聖之君六七作。周自後稷、公劉積德累仁，至乎古公季歷，肇基王業，而傳之文王。紂為天子，令行禁止，脯醢諸侯，莫敢不聽。文王三分天下有其二，而北面為臣，脫於囚虜。當此之時，可謂危矣。文王身當其事，而周公目睹其時，夫安得不危？文王危之，故雖險而卒平；紂唯易之，故雖強而卒傾。其在易，「蹇」而受之以解，危者使平也；「豐」而受之以旅，易者使傾也，皆文王與紂之事也。其餘卦爻，亦莫不然。茲因消息盈虛之理，求其為之者而不得，以為易實使之也。夫極於大者，小或有所遺；精於小者，大或有所局。唯易之為書，廣大悉備，是以其道甚大，而百物不廢也。然苟能戒懼以終始者，其要歸於無咎，此則易之道也。是故君子有終身之憂，而無一朝之患。其於是書，雖曰未學，吾必謂之學矣。夫乾，天下之至健也，德行恆易以知險。夫坤，天下之至順也，德行恆簡以知阻。能說諸心，能研諸侯之慮，定天下之吉凶，成天下之亹亹者。是故變化云為，吉事有祥，象事知器，佔事知來。天地設位，聖人成能。人謀鬼謀，百姓與能。八卦以象告，爻彖以情言。剛柔雜居，而吉凶可見矣。變動以利言，吉凶以情遷。是故愛惡相攻而吉凶生，遠近相取而悔吝生，情偽相感而利害生。凡易之情，近而不相得則兇，或害之，悔且吝。將叛者其辭慚，中心疑者其辭枝。吉人之辭寡，躁人之辭多，誣善之人其辭遊，失其守者其辭屈。前章既言易之辭危，而知懼者可以無咎，此章遂申言易本於乾坤，以乾坤而成爻象，以易簡而知險阻，至於愛惡情偽，枝遊慚屈，無所遁其情，是故其辭不得不危也。夫爻象雖皆出於乾坤，然八卦既成列矣，則六子之德行不得不與乾坤異。乾之健確然，故恆易。坤之順隤然，故恆簡。震坎艮，剛而雜乎柔，故多險。巽離兌，柔而雜乎剛，故多阻。以乾坤之易簡，知爻象之險阻，則能說諸心，諸研諸慮。以此定天下之吉凶，則無不定；以此成天下之事業，則無不成。「亹亹」，勉也，事業之所成也。「侯之」二字衍文，蘇氏已得之。之王弼例引用此文，亦無「侯之」二字，韓康伯以來衍之矣。雲者，言也。為者，動也。言動象佔，所謂「聖人之道四焉」者也。「變化云為」，則所謂「擬議以成變化」是也。「吉事有祥」，則言動之幾，吉之先見是也。「象事知器」，則「備物致用」，「立成器以為天下利」是也。佔事知來，則所謂「無有遠近幽深，遂知來物」是也。兼斯四者，聖人所以與天地參者乎？故曰「天地設位，聖人成能」。至於明則謀之人，幽則謀之鬼，雖百姓之愚，亦可使與能之矣。猶中庸所謂「夫婦之愚可以與知焉，夫婦之不肖可以能行焉」。蓋聖人與民同患，而所以開覺延納之者如此。百姓與能，故謀乎人鬼，聖人成能，故贊乎天地也。一卦之象可復八卦，是謂以象告；屯、蒙、需、訟，初九、六二，是謂以情言。變而通之以盡利，是謂以利言。吉凶悔吝生乎動，是謂以情遷。遠近者言其地，愛惡者言其情，情偽者言其德，或相得或不相得，或有害或無害，斯吉凶悔吝之所從生也。其義則爻象之辭備之矣。叛者恧其心，故其辭慚；疑者惑其志，故其辭枝；誣善之人難於指實，故其辭遊；失其守者難以求信，故其辭屈。諸如此類，作易者各準其情而為之辭，蓋不止於是。學者詳論而深思焉，則得之矣。臨川王氏曰：六者之辭，於易無有，其或然歟！周易經傳集解卷三十四。",-1)])])}const f=t(r,[["render",c]]);export{_ as __pageData,f as default};
